function build({entry=1,buildingSize=1,gate=4}={}){
 const xs=[0,6,...Array.from({length:5},(_,i)=>8+(i+1)*(gate+8))];
 const us=[refs[0].U*entry,refs[2].U*buildingSize**5,...['N04','N05','N06','C07','N08'].map(id=>old.get(id).Ueq_J)];
 const ys=us.map(Math.log10),h=xs.slice(1).map((v,i)=>v-xs[i]),d=h.map((v,i)=>(ys[i+1]-ys[i])/v);
 const slopes=xs.map((v,i)=>i===0?d[0]:i===xs.length-1?d.at(-1):3*(h[i-1]+h[i])/((2*h[i]+h[i-1])/d[i-1]+(h[i]+2*h[i-1])/d[i]));
 function at(x){
  const exact=xs.indexOf(x);if(exact>=0)return us[exact];
  let i=0;while(i<xs.length-2&&x>xs[i+1])i++;
  const t=(x-xs[i])/h[i];
